// Generated by scripts/sync-film.mjs from motion-film/src/props/WeddingDayNight.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { palette } from "../theme/palette";

/*
 * Reception props: cut-paper chandeliers (tiered scalloped paper, gold edges, candle flames,
 * pearl drops) and champagne flutes. Scene space.
 */

const PAPER = "#F4E9D4";
const PAPER_SHADE = "#DCC9A6";

const Tier: React.FC<{ w: number; y: number; t: number; drop: number }> = ({ w, y, t, drop }) => {
  const h = w * 0.16;
  const n = Math.max(6, Math.round(w / 22));
  const step = w / n;
  let fringe = `M${-w / 2} ${y}`;
  for (let i = 0; i < n; i++) fringe += ` Q${-w / 2 + (i + 0.5) * step} ${y + drop} ${-w / 2 + (i + 1) * step} ${y}`;
  return (
    <g>
      {/* candles on the rim */}
      {new Array(Math.max(3, Math.round(n / 2))).fill(0).map((_, i, arr) => {
        const x = -w / 2 + ((i + 0.5) * w) / arr.length;
        const fl = 1 + Math.sin(t * 5 + i * 1.7) * 0.12;
        return (
          <g key={i}>
            <circle cx={x} cy={y - h - 22} r={16} fill="#FFE2A0" opacity={0.28} />
            <rect x={x - 3} y={y - h - 14} width={6} height={14} fill={palette.ivoryLight} />
            <path d={`M${x} ${y - h - 14 - 16 * fl} C${x + 5} ${y - h - 20} ${x + 4} ${y - h - 14} ${x} ${y - h - 14} C${x - 4} ${y - h - 14} ${x - 5} ${y - h - 20} ${x} ${y - h - 14 - 16 * fl} Z`} fill={palette.fireMid} />
          </g>
        );
      })}
      {/* band */}
      <path d={`M${-w / 2} ${y - h} L${w / 2} ${y - h} L${w / 2} ${y} L${-w / 2} ${y} Z`} fill={PAPER} />
      <path d={`M${-w / 2} ${y - h} L${-w / 2 + w * 0.12} ${y - h} L${-w / 2 + w * 0.12} ${y} L${-w / 2} ${y} Z`} fill={PAPER_SHADE} />
      <path d={`M${w / 2 - w * 0.12} ${y - h} L${w / 2} ${y - h} L${w / 2} ${y} L${w / 2 - w * 0.12} ${y} Z`} fill={PAPER_SHADE} opacity={0.7} />
      {/* cut-out lattice on the band */}
      {new Array(n).fill(0).map((_, i) => (
        <path key={i} d={`M${-w / 2 + (i + 0.5) * step} ${y - h * 0.8} l${step * 0.22} ${h * 0.3} l${-step * 0.22} ${h * 0.3} l${-step * 0.22} ${-h * 0.3} Z`} fill="#3A2436" opacity={0.35} />
      ))}
      <rect x={-w / 2} y={y - h - 1} width={w} height={2.4} fill={palette.goldLight} />
      {/* scalloped fringe */}
      <path d={`${fringe} Z`} fill={PAPER} />
      <path d={fringe} fill="none" stroke={palette.gold} strokeWidth={1.6} />
      {new Array(n + 1).fill(0).map((_, i) => (
        <g key={`p${i}`}>
          <rect x={-w / 2 + i * step - 0.4} y={y} width={0.8} height={drop * 1.8} fill={palette.goldLight} opacity={0.8} />
          <circle cx={-w / 2 + i * step} cy={y + drop * 1.8 + 3} r={3} fill={i % 2 ? "#FFF6E4" : "url(#foil)"} />
        </g>
      ))}
    </g>
  );
};

/** Cut-paper chandelier hanging from (x, top) with its body at y; `swing` degrees about the thread top. */
export const PaperChandelier: React.FC<{ x: number; y: number; s?: number; swing?: number; t: number; top?: number }> = ({ x, y, s = 1, swing = 0, t, top = -200 }) => (
  <g transform={`rotate(${swing} ${x} ${top})`}>
    <rect x={x - 0.7} y={top} width={1.4} height={y - top} fill={palette.goldLight} opacity={0.8} />
    <g transform={`translate(${x} ${y}) scale(${s})`}>
      <circle cx={0} cy={110} r={170} fill="#FFE6B0" opacity={0.08} />
      <circle cx={0} cy={110} r={110} fill="#FFE6B0" opacity={0.1} />
      {/* crown */}
      <path d="M-14 0 L14 0 L22 20 L-22 20 Z" fill={PAPER} />
      <circle cx={0} cy={-4} r={6} fill="url(#foil)" />
      <path d="M-22 20 C-22 6 22 6 22 20" fill="none" stroke={palette.gold} strokeWidth={1.5} />
      {/* chains to tiers */}
      {[-1, 1].map((k) => (
        <g key={k}>
          <path d={`M${k * 10} 20 L${k * 60} 80`} stroke={palette.goldLight} strokeWidth={1} />
          <path d={`M${k * 16} 20 L${k * 88} 150`} stroke={palette.goldLight} strokeWidth={1} />
        </g>
      ))}
      <Tier w={96} y={84} t={t} drop={16} />
      <Tier w={150} y={152} t={t + 1} drop={20} />
      <Tier w={196} y={224} t={t + 2} drop={24} />
      {/* central drop */}
      <rect x={-0.6} y={224} width={1.2} height={70} fill={palette.goldLight} />
      <path d="M0 290 L10 306 L0 330 L-10 306 Z" fill="url(#foil)" />
    </g>
  </g>
);

/** Champagne flute at (x, y) = where the hand holds the stem; tilt in degrees. */
export const Flute: React.FC<{ x: number; y: number; s?: number; tilt?: number; fill?: string; rim?: string }> = ({ x, y, s = 1, tilt = 0, fill = "#F3DFA8", rim = palette.goldPale }) => (
  <g transform={`translate(${x} ${y}) rotate(${tilt}) scale(${s})`}>
    <path d="M-12 -70 L12 -70 C12 -40 8 -26 2 -20 L2 10 L12 16 L-12 16 L-2 10 L-2 -20 C-8 -26 -12 -40 -12 -70 Z" fill={fill} opacity={0.9} />
    <path d="M-10 -56 L10 -56 C10 -40 7 -28 0 -24 C-7 -28 -10 -40 -10 -56 Z" fill="#E7B95E" opacity={0.8} />
    <path d="M-12 -70 L12 -70" stroke={rim} strokeWidth={2} />
    <circle cx={-4} cy={-48} r={1.6} fill="#FFFFFF" opacity={0.8} />
    <circle cx={3} cy={-38} r={1.2} fill="#FFFFFF" opacity={0.7} />
  </g>
);
